1	// ---------------------------------------------------------------------------
2	// Shared API utilities for public storefront endpoints
3	// ---------------------------------------------------------------------------
4	
5	export const CORS_HEADERS: Record<string, string> = {
6	  "Access-Control-Allow-Origin": "*",
7	  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
8	  "Access-Control-Allow-Headers": "Content-Type",
9	};
10	
11	export const SHOP_RE = /^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/;
12	
13	/**
14	 * Return a JSON response with CORS headers attached.
15	 */
16	export function corsJson(data: unknown, init?: { status?: number; headers?: Record<string, string> }): Response {
17	  return Response.json(data, {
18	    status: init?.status ?? 200,
19	    headers: { ...CORS_HEADERS, ...init?.headers },
20	  });
21	}
22	
23	/**
24	 * Handle OPTIONS preflight requests.
25	 */
26	export function corsOptions(): Response {
27	  return new Response(null, { status: 204, headers: CORS_HEADERS });
28	}
29	
30	/**
31	 * Validate a Shopify shop domain. Returns an error response if invalid, or null if valid.
32	 */
33	export function validateShop(shop: string | null): Response | null {
34	  if (!shop || !SHOP_RE.test(shop)) {
35	    return corsJson({ error: "Invalid or missing shop parameter" }, { status: 400 });
36	  }
37	  return null;
38	}
39	
40	/**
41	 * Sanitize user-provided CSS to prevent XSS vectors.
42	 */
43	export function sanitizeCss(css: string): string {
44	  if (!css) return "";
45	  return css
46	    .replace(/@import\s/gi, "/* blocked */ ")
47	    .replace(/url\s*\(\s*["']?\s*javascript:/gi, "url(#")
48	    .replace(/url\s*\(\s*["']?\s*data:\s*text\/html/gi, "url(#")
49	    .replace(/expression\s*\(/gi, "/* blocked */(")
50	    .replace(/behavior\s*:/gi, "/* blocked */:")
51	    .replace(/-moz-binding\s*:/gi, "/* blocked */:")
52	    .replace(/-ms-filter\s*:/gi, "/* blocked */:")
53	    .replace(/<\/style/gi, "/* blocked */")
54	    .replace(/<script/gi, "/* blocked */");
55	}
