1	// ---------------------------------------------------------------------------
2	// Shopify Billing Integration — Subscription lifecycle management
3	// Uses Shopify Admin GraphQL API (2026-01)
4	// ---------------------------------------------------------------------------
5	
6	import db from "../db.server";
7	import { PLANS, getPlan } from "../lib/plans";
8	
9	// ---------------------------------------------------------------------------
10	// Types
11	// ---------------------------------------------------------------------------
12	
13	export interface BillingContext {
14	  admin: { graphql: (query: string, options?: { variables?: Record<string, unknown> }) => Promise<{ json: () => Promise<unknown> }> };
15	  session: { shop: string };
16	}
17	
18	interface AppSubscriptionCreateResponse {
19	  data: {
20	    appSubscriptionCreate: {
21	      appSubscription: { id: string } | null;
22	      confirmationUrl: string | null;
23	      userErrors: { field: string; message: string }[];
24	    };
25	  };
26	}
27	
28	interface AppSubscriptionCancelResponse {
29	  data: {
30	    appSubscriptionCancel: {
31	      appSubscription: { id: string; status: string } | null;
32	      userErrors: { field: string; message: string }[];
33	    };
34	  };
35	}
36	
37	interface CurrentAppInstallationResponse {
38	  data: {
39	    currentAppInstallation: {
40	      activeSubscriptions: {
41	        id: string;
42	        name: string;
43	        status: string;
44	        createdAt: string;
45	        currentPeriodEnd: string | null;
46	        test: boolean;
47	        lineItems: {
48	          plan: {
49	            pricingDetails:
50	              | { price: { amount: string; currencyCode: string } }
51	              | { interval: string; base: { amount: string; currencyCode: string } };
52	          };
53	        }[];
54	      }[];
55	    };
56	  };
57	}
58	
59	export interface ActiveShopifySubscription {
60	  id: string;
61	  name: string;
62	  status: string;
63	  createdAt: string;
64	  currentPeriodEnd: string | null;
65	  test: boolean;
66	}
67	
68	// ---------------------------------------------------------------------------
69	// GraphQL documents
70	// ---------------------------------------------------------------------------
71	
72	const APP_SUBSCRIPTION_CREATE_MUTATION = `
73	  mutation appSubscriptionCreate(
74	    $name: String!
75	    $lineItems: [AppSubscriptionLineItemInput!]!
76	    $returnUrl: URL!
77	    $test: Boolean
78	  ) {
79	    appSubscriptionCreate(
80	      name: $name
81	      lineItems: $lineItems
82	      returnUrl: $returnUrl
83	      test: $test
84	    ) {
85	      appSubscription {
86	        id
87	      }
88	      confirmationUrl
89	      userErrors {
90	        field
91	        message
92	      }
93	    }
94	  }
95	`;
96	
97	const APP_SUBSCRIPTION_CANCEL_MUTATION = `
98	  mutation appSubscriptionCancel($id: ID!) {
99	    appSubscriptionCancel(id: $id) {
100	      appSubscription {
101	        id
102	        status
103	      }
104	      userErrors {
105	        field
106	        message
107	      }
108	    }
109	  }
110	`;
111	
112	const CURRENT_APP_INSTALLATION_QUERY = `
113	  query currentAppInstallation {
114	    currentAppInstallation {
115	      activeSubscriptions {
116	        id
117	        name
118	        status
119	        createdAt
120	        currentPeriodEnd
121	        test
122	        lineItems {
123	          plan {
124	            pricingDetails {
125	              ... on AppRecurringPricing {
126	                price {
127	                  amount
128	                  currencyCode
129	                }
130	                interval
131	              }
132	              ... on AppUsagePricing {
133	                cappedAmount {
134	                  amount
135	                  currencyCode
136	                }
137	                terms
138	              }
139	            }
140	          }
141	        }
142	      }
143	    }
144	  }
145	`;
146	
147	// ---------------------------------------------------------------------------
148	// createSubscription
149	// Creates a Shopify app subscription and returns the hosted confirmation URL.
150	// The merchant must visit confirmationUrl to approve the charge.
151	// ---------------------------------------------------------------------------
152	
153	export async function createSubscription(
154	  context: BillingContext,
155	  planId: string,
156	  billingInterval: "monthly" | "annual",
157	): Promise<{ confirmationUrl: string; subscriptionId: string }> {
158	  const plan = getPlan(planId);
159	
160	  if (plan.id === "free") {
161	    throw new Error("Free plan does not require a Shopify subscription.");
162	  }
163	
164	  const price = billingInterval === "annual" ? plan.annualPrice : plan.price;
165	  const interval = billingInterval === "annual" ? "ANNUAL" : "EVERY_30_DAYS";
166	  const planName = `Size Chart & Recommender — ${plan.name} (${billingInterval})`;
167	
168	  const returnUrl = `https://${context.session.shop}/admin/apps`;
169	
170	  const response = await context.admin.graphql(APP_SUBSCRIPTION_CREATE_MUTATION, {
171	    variables: {
172	      name: planName,
173	      lineItems: [
174	        {
175	          plan: {
176	            appRecurringPricingDetails: {
177	              price: { amount: price, currencyCode: "USD" },
178	              interval,
179	            },
180	          },
181	        },
182	      ],
183	      returnUrl,
184	      test: process.env.NODE_ENV !== "production",
185	    },
186	  });
187	
188	  const body = (await response.json()) as AppSubscriptionCreateResponse;
189	  const result = body.data.appSubscriptionCreate;
190	
191	  if (result.userErrors.length > 0) {
192	    const messages = result.userErrors.map((e) => e.message).join(", ");
193	    throw new Error(`Shopify billing error: ${messages}`);
194	  }
195	
196	  if (!result.confirmationUrl || !result.appSubscription) {
197	    throw new Error("Shopify did not return a confirmation URL.");
198	  }
199	
200	  // Persist a pending subscription record in local DB
201	  await db.subscription.upsert({
202	    where: { shop: context.session.shop },
203	    create: {
204	      shop: context.session.shop,
205	      planId,
206	      billingInterval,
207	      shopifySubscriptionId: result.appSubscription.id,
208	      status: "pending",
209	    },
210	    update: {
211	      planId,
212	      billingInterval,
213	      shopifySubscriptionId: result.appSubscription.id,
214	      status: "pending",
215	    },
216	  });
217	
218	  return {
219	    confirmationUrl: result.confirmationUrl,
220	    subscriptionId: result.appSubscription.id,
221	  };
222	}
223	
224	// ---------------------------------------------------------------------------
225	// cancelSubscription
226	// Cancels the merchant's current active Shopify subscription.
227	// ---------------------------------------------------------------------------
228	
229	export async function cancelSubscription(
230	  context: BillingContext,
231	): Promise<void> {
232	  const existing = await db.subscription.findUnique({
233	    where: { shop: context.session.shop },
234	  });
235	
236	  if (!existing?.shopifySubscriptionId) {
237	    throw new Error("No active subscription found to cancel.");
238	  }
239	
240	  const response = await context.admin.graphql(APP_SUBSCRIPTION_CANCEL_MUTATION, {
241	    variables: { id: existing.shopifySubscriptionId },
242	  });
243	
244	  const body = (await response.json()) as AppSubscriptionCancelResponse;
245	  const result = body.data.appSubscriptionCancel;
246	
247	  if (result.userErrors.length > 0) {
248	    const messages = result.userErrors.map((e) => e.message).join(", ");
249	    throw new Error(`Shopify cancel error: ${messages}`);
250	  }
251	
252	  // Mark subscription as cancelled in local DB
253	  await db.subscription.update({
254	    where: { shop: context.session.shop },
255	    data: {
256	      status: "cancelled",
257	      planId: "free",
258	      shopifySubscriptionId: null,
259	    },
260	  });
261	}
262	
263	// ---------------------------------------------------------------------------
264	// getActiveSubscription
265	// Fetches the merchant's current active subscription from Shopify.
266	// Returns null when on the free plan (no active charge).
267	// ---------------------------------------------------------------------------
268	
269	export async function getActiveSubscription(
270	  context: BillingContext,
271	): Promise<ActiveShopifySubscription | null> {
272	  const response = await context.admin.graphql(CURRENT_APP_INSTALLATION_QUERY);
273	  const body = (await response.json()) as CurrentAppInstallationResponse;
274	
275	  const subs =
276	    body.data.currentAppInstallation.activeSubscriptions;
277	
278	  if (!subs || subs.length === 0) return null;
279	
280	  // Prefer ACTIVE status; fall back to first entry
281	  const active =
282	    subs.find((s) => s.status === "ACTIVE") ?? subs[0];
283	
284	  return {
285	    id: active.id,
286	    name: active.name,
287	    status: active.status,
288	    createdAt: active.createdAt,
289	    currentPeriodEnd: active.currentPeriodEnd,
290	    test: active.test,
291	  };
292	}
293	
294	// ---------------------------------------------------------------------------
295	// syncSubscription
296	// Reconciles Shopify subscription status with the local DB record.
297	// Intended to be called from webhook handlers.
298	// ---------------------------------------------------------------------------
299	
300	export async function syncSubscription(
301	  shop: string,
302	  shopifySubscriptionId: string,
303	  shopifyStatus: string,
304	): Promise<void> {
305	  const normalizedStatus = shopifyStatus.toLowerCase();
306	
307	  // Map Shopify statuses to local statuses
308	  const statusMap: Record<string, string> = {
309	    active: "active",
310	    cancelled: "cancelled",
311	    declined: "cancelled",
312	    expired: "cancelled",
313	    frozen: "frozen",
314	    pending: "pending",
315	  };
316	
317	  const localStatus = statusMap[normalizedStatus] ?? "pending";
318	
319	  // Resolve planId from the subscription name stored in the local record
320	  const existing = await db.subscription.findFirst({
321	    where: { shop, shopifySubscriptionId },
322	  });
323	
324	  const resolvedPlanId = (() => {
325	    if (localStatus === "cancelled") return "free";
326	    if (existing?.planId) return existing.planId;
327	    // Attempt to match by subscription name if we have no local record
328	    for (const plan of PLANS) {
329	      if (
330	        existing?.planId === plan.id ||
331	        shopifySubscriptionId.includes(plan.id)
332	      ) {
333	        return plan.id;
334	      }
335	    }
336	    return "free";
337	  })();
338	
339	  await db.subscription.upsert({
340	    where: { shop },
341	    create: {
342	      shop,
343	      planId: resolvedPlanId,
344	      billingInterval: existing?.billingInterval ?? "monthly",
345	      shopifySubscriptionId,
346	      status: localStatus,
347	    },
348	    update: {
349	      shopifySubscriptionId,
350	      status: localStatus,
351	      ...(localStatus === "cancelled" ? { planId: "free" } : {}),
352	    },
353	  });
354	}
355	
356	// ---------------------------------------------------------------------------
357	// getLocalSubscription
358	// Reads the shop's subscription record from the local DB.
359	// Returns a default free-plan record if none exists.
360	// ---------------------------------------------------------------------------
361	
362	export async function getLocalSubscription(shop: string) {
363	  const record = await db.subscription.findUnique({ where: { shop } });
364	
365	  if (!record) {
366	    return {
367	      shop,
368	      planId: "free",
369	      billingInterval: "monthly" as const,
370	      shopifySubscriptionId: null,
371	      status: "active",
372	      trialEndsAt: null,
373	    };
374	  }
375	
376	  return record;
377	}
