45	// ---------------------------------------------------------------------------
46	// Loader
47	// ---------------------------------------------------------------------------
48	
49	export const loader = async ({ request }: LoaderFunctionArgs) => {
50	  const { session } = await authenticate.admin(request);
51	  const shop = session.shop;
52	
53	  const url = new URL(request.url);
54	  const fromParam = url.searchParams.get("from");
55	  const toParam = url.searchParams.get("to");
56	  const presetParam = url.searchParams.get("preset") ?? "30d";
57	
58	  // Resolve current date range
59	  const now = new Date();
60	  let fromDate: Date;
61	  let toDate: Date = new Date(now);
62	  toDate.setHours(23, 59, 59, 999);
63	
64	  if (fromParam && toParam) {
65	    fromDate = new Date(fromParam);
66	    fromDate.setHours(0, 0, 0, 0);
67	    const parsedTo = new Date(toParam);
68	    parsedTo.setHours(23, 59, 59, 999);
69	    toDate = parsedTo;
70	  } else {
71	    const daysBack = presetParam === "7d" ? 7 : presetParam === "90d" ? 90 : 30;
72	    fromDate = new Date(Date.now() - daysBack * 24 * 60 * 60 * 1000);
73	    fromDate.setHours(0, 0, 0, 0);
74	  }
75	
76	  const dateRange = { from: fromDate, to: toDate };
77	
78	  // Previous period for trend comparison (same duration, shifted back)
79	  const rangeMs = toDate.getTime() - fromDate.getTime();
80	  const prevToDate = new Date(fromDate.getTime() - 1);
81	  prevToDate.setHours(23, 59, 59, 999);
82	  const prevFromDate = new Date(prevToDate.getTime() - rangeMs);
83	  prevFromDate.setHours(0, 0, 0, 0);
84	  const prevDateRange = { from: prevFromDate, to: prevToDate };
85	
86	  const subscription = await db.subscription.findUnique({ where: { shop } });
87	  const plan = getPlan(subscription?.planId ?? "free");
88	  const canViewAnalytics = hasFeature(plan.id, "analytics");
89	
90	  if (!canViewAnalytics) {
91	    return {
92	      plan,
93	      canViewAnalytics: false as const,
94	      analytics: null,
95	      preset: presetParam,
96	      fromDate: fromDate.toISOString().split("T")[0],
97	      toDate: toDate.toISOString().split("T")[0],
98	    };
99	  }
100	
101	  // Fetch all analytics data using the server helpers
102	  const [summary, summaryPrev, funnel, topCharts, dailyTrend] = await Promise.all([
103	    getAnalyticsSummary(shop, dateRange),
104	    getAnalyticsSummary(shop, prevDateRange),
105	    getConversionFunnel(shop, dateRange),
106	    getTopCharts(shop, dateRange, 5),
107	    getDailyTrend(shop, dateRange, "view"),
