131	
132	function StatCard({
133	  label,
134	  value,
135	  prevValue,
136	  isLoading,
137	}: {
138	  label: string;
139	  value: number;
140	  prevValue: number;
141	  isLoading: boolean;
142	}) {
143	  const diff = value - prevValue;
144	  const pct = prevValue > 0 ? Math.round((diff / prevValue) * 100) : 0;
145	  const isUp = diff >= 0;
146	
147	  return (
148	    <Box
149	      background="bg-surface"
150	      borderWidth="025"
151	      borderColor="border"
152	      borderRadius="200"
153	      padding="400"
154	    >
155	      <BlockStack gap="100">
156	        <Text as="p" variant="bodySm" tone="subdued">{label}</Text>
157	        <Text as="p" variant="headingXl" fontWeight="bold">
158	          {isLoading ? "—" : value.toLocaleString()}
159	        </Text>
160	        {!isLoading && prevValue > 0 && (
161	          <InlineStack gap="100" blockAlign="center">
162	            <Text
163	              as="span"
164	              variant="bodySm"
165	              tone={isUp ? "success" : "critical"}
166	            >
167	              {isUp ? "+" : ""}{pct}%
168	            </Text>
169	            <Text as="span" variant="bodySm" tone="subdued">vs prior period</Text>
170	          </InlineStack>
171	        )}
172	        {!isLoading && prevValue === 0 && (
173	          <Text as="p" variant="bodySm" tone="subdued">No prior data</Text>
174	        )}
175	      </BlockStack>
176	    </Box>
177	  );
178	}
