183	
184	function BarChart({ data, isLoading }: { data: DailyDataPoint[]; isLoading: boolean }) {
185	  if (isLoading) {
186	    return (
187	      <div style={{ height: "250px", display: "flex", alignItems: "center", justifyContent: "center" }}>
188	        <Text as="p" variant="bodyMd" tone="subdued">Loading chart data…</Text>
189	      </div>
190	    );
191	  }
192	
193	  const max = Math.max(...data.map((d) => d.count), 1);
194	
195	  // For readability, show at most 30 data points — group into weekly if needed
196	  let displayData = data;
197	  if (data.length > 30) {
198	    const weekBuckets: Record<string, number> = {};
199	    for (const pt of data) {
200	      const d = new Date(pt.date + "T12:00:00Z");
201	      const weekStart = new Date(d);
202	      weekStart.setDate(d.getDate() - d.getDay());
203	      const wk = weekStart.toISOString().slice(0, 10);
204	      weekBuckets[wk] = (weekBuckets[wk] ?? 0) + pt.count;
205	    }
206	    displayData = Object.entries(weekBuckets).map(([date, count]) => ({ date, count }));
207	  }
208	
209	  const formatLabel = (dateStr: string) =>
210	    new Date(dateStr + "T12:00:00Z").toLocaleDateString("en-US", {
211	      month: "short",
212	      day: "numeric",
213	    });
214	
215	  return (
216	    <BlockStack gap="200">
217	      <div style={{ display: "flex", alignItems: "flex-end", gap: "3px", height: "200px" }}>
218	        {displayData.map((d, i) => (
219	          <Tooltip key={i} content={`${formatLabel(d.date)}: ${d.count} views`}>
220	            <div
221	              style={{
222	                flex: 1,
223	                display: "flex",
224	                flexDirection: "column",
225	                justifyContent: "flex-end",
226	                height: "200px",
227	              }}
228	            >
229	              <div
230	                style={{
231	                  background: "var(--p-color-bg-fill-brand)",
232	                  borderRadius: "3px 3px 0 0",
233	                  height: `${Math.max((d.count / max) * 200, d.count > 0 ? 4 : 0)}px`,
234	                  minHeight: d.count > 0 ? "4px" : "0",
235	                  transition: "height 0.2s ease",
236	                }}
237	              />
238	            </div>
239	          </Tooltip>
240	        ))}
241	      </div>
242	      <InlineStack align="space-between">
243	        <Text as="p" variant="bodySm" tone="subdued">
244	          {displayData[0] ? formatLabel(displayData[0].date) : ""}
245	        </Text>
246	        <Text as="p" variant="bodySm" tone="subdued">
247	          {displayData[displayData.length - 1] ? formatLabel(displayData[displayData.length - 1].date) : ""}
248	        </Text>
249	      </InlineStack>
250	    </BlockStack>
251	  );
