384	// CSV export helper (runs in browser)
385	// ---------------------------------------------------------------------------
386	
387	function exportCsv(data: AnalyticsData, preset: string) {
388	  const rows: string[] = [
389	    "Date,Views",
390	    ...data.dailyTrend.map((pt) => `${pt.date},${pt.count}`),
391	    "",
392	    "Metric,Value",
393	    `Total Views,${data.summary.totalViews}`,
394	    `Total Clicks,${data.summary.totalClicks}`,
395	    `Total Recommendations,${data.summary.totalRecommendations}`,
396	    `Total Conversions,${data.summary.totalConversions}`,
397	    "",
398	    "Rank,Chart,Views,Clicks,Recommendations,Conversions",
399	    ...data.topCharts.map(
400	      (c, i) =>
401	        `${i + 1},${c.name},${c.views},${c.clicks},${c.recommendations},${c.conversions}`,
402	    ),
403	  ];
404	
405	  const blob = new Blob([rows.join("\n")], { type: "text/csv" });
406	  const url = URL.createObjectURL(blob);
407	  const a = document.createElement("a");
408	  a.href = url;
409	  a.download = `size-chart-analytics-${preset}-${new Date().toISOString().slice(0, 10)}.csv`;
410	  a.click();
411	  URL.revokeObjectURL(url);
412	}
