94	export const action = async ({ request }: ActionFunctionArgs) => {
95	  const { session } = await authenticate.admin(request);
96	  const shop = session.shop;
97	  const formData = await request.formData();
98	  const intent = formData.get("intent") as string;
99	
100	  try {
101	    switch (intent) {
102	      case "export-data": {
103	        const charts = await db.sizeChart.findMany({
104	          where: { shop },
105	          include: { assignments: true },
106	        });
107	        const payload = {
108	          exportedAt: new Date().toISOString(),
109	          shop,
110	          charts: charts.map((c) => ({
111	            id: c.id,
112	            name: c.name,
113	            type: c.type,
114	            category: c.category,
115	            data: c.data,
116	            isDefault: c.isDefault,
117	            status: c.status,
118	            createdAt: c.createdAt.toISOString(),
119	            assignments: c.assignments.map((a) => ({
120	              assignmentType: a.assignmentType,
121	              assignmentValue: a.assignmentValue,
122	            })),
123	          })),
124	        };
125	        return {
126	          ok: true,
127	          intent: "export-data",
128	          message: `${charts.length} chart${charts.length === 1 ? "" : "s"} exported`,
129	          exportData: JSON.stringify(payload, null, 2),
130	        };
131	      }
132	
133	      case "import-data": {
134	        const subscription = await db.subscription.findUnique({ where: { shop } });
135	        const plan = getPlan(subscription?.planId ?? "free");
136	        if (!hasFeature(plan.id, "csvImport")) {
137	          return { error: "Import requires the Starter plan or above", intent: "import-data" };
138	        }
139	
140	        const jsonRaw = formData.get("importJson") as string;
141	        if (!jsonRaw?.trim()) {
142	          return { error: "No JSON data provided", intent: "import-data" };
143	        }
144	        let parsed: {
145	          charts?: Array<{
146	            name: string;
147	            type?: string;
148	            category?: string;
149	            data?: string;
150	            isDefault?: boolean;
151	            status?: string;
152	            assignments?: Array<{ assignmentType: string; assignmentValue: string }>;
153	          }>;
154	        };
155	        try {
156	          parsed = JSON.parse(jsonRaw) as typeof parsed;
157	        } catch {
158	          return { error: "Invalid JSON format", intent: "import-data" };
159	        }
160	        if (!Array.isArray(parsed.charts)) {
161	          return { error: "JSON must contain a 'charts' array", intent: "import-data" };
162	        }
163	        let imported = 0;
164	        for (const chart of parsed.charts) {
165	          if (!chart.name) continue;
166	          const existing = await db.sizeChart.findFirst({
167	            where: { shop, name: chart.name },
168	          });
169	          if (existing) continue;
170	          await db.sizeChart.create({
171	            data: {
172	              shop,
173	              name: chart.name,
174	              type: chart.type ?? "table",
175	              category: chart.category ?? "general",
176	              data: chart.data ?? "{}",
177	              isDefault: chart.isDefault ?? false,
178	              status: chart.status ?? "draft",
179	              assignments: chart.assignments
180	                ? {
181	                    create: chart.assignments.map((a) => ({
182	                      shop,
183	                      assignmentType: a.assignmentType,
184	                      assignmentValue: a.assignmentValue,
185	                    })),
186	                  }
187	                : undefined,
188	            },
189	          });
190	          imported++;
191	        }
192	        return {
193	          ok: true,
194	          intent: "import-data",
195	          message: `${imported} chart${imported === 1 ? "" : "s"} imported successfully`,
196	        };
197	      }
198	
199	      case "reset-widget": {
200	        await db.widgetConfig.deleteMany({ where: { shop } });
201	        return { ok: true, intent: "reset-widget", message: "Widget settings reset to defaults" };
202	      }
203	
204	      case "reset-analytics": {
205	        const deleted = await db.analyticsEvent.deleteMany({ where: { shop } });
206	        return {
207	          ok: true,
208	          intent: "reset-analytics",
209	          message: `${deleted.count} analytics event${deleted.count === 1 ? "" : "s"} cleared`,
210	        };
211	      }
212	
213	      case "delete-all-charts": {
214	        const confirm = formData.get("confirmText") as string;
215	        if (confirm !== "DELETE") {
216	          return { error: "Type DELETE to confirm", intent: "delete-all-charts" };
217	        }
218	        await db.chartAssignment.deleteMany({ where: { shop } });
219	        const deleted = await db.sizeChart.deleteMany({ where: { shop } });
220	        return {
221	          ok: true,
222	          intent: "delete-all-charts",
223	          message: `${deleted.count} chart${deleted.count === 1 ? "" : "s"} deleted`,
224	        };
225	      }
226	
227	      case "reset-app": {
228	        const confirm = formData.get("confirmText") as string;
229	        if (confirm !== "DELETE") {
230	          return { error: "Type DELETE to confirm", intent: "reset-app" };
231	        }
232	        await Promise.all([
233	          db.widgetConfig.deleteMany({ where: { shop } }),
234	          db.recommenderConfig.deleteMany({ where: { shop } }),
235	          db.analyticsEvent.deleteMany({ where: { shop } }),
236	        ]);
237	        return {
238	          ok: true,
239	          intent: "reset-app",
240	          message: "App data reset. Widget, recommender and analytics cleared.",
241	        };
242	      }
243	
244	      default:
245	        return { error: "Unknown action", intent };
246	    }
247	  } catch (error) {
