1	import type { LoaderFunctionArgs } from "react-router";
2	import db from "../db.server";
3	import { corsOptions, corsJson, validateShop } from "../lib/api.server";
4	import { checkRateLimit } from "../lib/rate-limit.server";
5	
6	// ---------------------------------------------------------------------------
7	// Types
8	// ---------------------------------------------------------------------------
9	
10	interface ChartData {
11	  headers: string[];
12	  units: { default: string; available: string[] };
13	  rows: Record<string, string>[];
14	}
15	
16	interface SizeChartResponse {
17	  id: string;
18	  name: string;
19	  category: string;
20	  type: string;
21	  data: ChartData;
22	  assignmentType?: string;
23	}
24	
25	// ---------------------------------------------------------------------------
26	// Assignment priority lookup
27	// Priority: product (1) > collection (2) > product_type (3) > tag (4) > all (5)
28	// ---------------------------------------------------------------------------
29	
30	const ASSIGNMENT_PRIORITY: Record<string, number> = {
31	  product: 1,
32	  collection: 2,
33	  product_type: 3,
34	  tag: 4,
35	  all: 5,
36	};
37	
38	// ---------------------------------------------------------------------------
39	// Loader — GET /api/size-chart
40	// Query params: shop (required), productId?, collectionId?, chartId?
41	// ---------------------------------------------------------------------------
42	
43	export const loader = async ({ request }: LoaderFunctionArgs) => {
44	  if (request.method === "OPTIONS") {
45	    return corsOptions();
46	  }
47	
48	  const url = new URL(request.url);
49	  const shop = url.searchParams.get("shop");
50	  const chartId = url.searchParams.get("chartId");
51	  const productId = url.searchParams.get("productId");
52	  const collectionId = url.searchParams.get("collectionId");
53	
54	  const shopError = validateShop(shop);
55	  if (shopError) return shopError;
56	
57	  const rateLimitError = checkRateLimit("size-chart:" + shop!, 120);
58	  if (rateLimitError) return rateLimitError;
59	
60	  try {
61	    // Direct lookup by chartId
62	    if (chartId) {
63	      const chart = await db.sizeChart.findFirst({
64	        where: { id: chartId, shop: shop!, status: "active" },
65	      });
66	
67	      if (!chart) {
68	        return corsJson({ error: "Chart not found" }, { status: 404 });
69	      }
70	
71	      const parsedData = parseChartData(chart.data);
72	      const response: SizeChartResponse = {
73	        id: chart.id,
74	        name: chart.name,
75	        category: chart.category,
76	        type: chart.type,
77	        data: parsedData,
78	      };
79	
80	      return corsJson(response);
81	    }
82	
83	    // Build lookup values from provided params
84	    // We'll fetch all active assignments for this shop and filter in priority order
85	    const lookupValues: Array<{ type: string; value: string }> = [];
86	
87	    if (productId) {
88	      lookupValues.push({ type: "product", value: productId });
89	    }
90	    if (collectionId) {
91	      lookupValues.push({ type: "collection", value: collectionId });
92	    }
93	
94	    if (lookupValues.length === 0) {
95	      return corsJson(
96	        { error: "At least one of chartId, productId, or collectionId is required" },
97	        { status: 400 },
98	      );
99	    }
100	
101	    // Always include the wildcard "all" fallback
102	    lookupValues.push({ type: "all", value: "*" });
103	
104	    // Fetch all assignments that could match, ordered by the chart's status
105	    const assignments = await db.chartAssignment.findMany({
106	      where: {
107	        shop: shop!,
108	        OR: lookupValues.map(({ type, value }) => ({
109	          assignmentType: type,
110	          assignmentValue: value,
111	        })),
112	      },
113	      include: {
114	        sizeChart: true,
115	      },
116	    });
117	
118	    // Filter to only active charts and pick by priority
119	    const activeAssignments = assignments.filter(
120	      (a) => a.sizeChart.status === "active",
121	    );
122	
123	    if (activeAssignments.length === 0) {
124	      return corsJson(
125	        { error: "No size chart found for the given product" },
126	        { status: 404 },
127	      );
128	    }
129	
130	    // Sort by priority — lowest number = highest priority
131	    activeAssignments.sort((a, b) => {
132	      const pa = ASSIGNMENT_PRIORITY[a.assignmentType] ?? 99;
133	      const pb = ASSIGNMENT_PRIORITY[b.assignmentType] ?? 99;
134	      return pa - pb;
135	    });
136	
137	    const best = activeAssignments[0];
138	    const parsedData = parseChartData(best.sizeChart.data);
139	
140	    const response: SizeChartResponse = {
141	      id: best.sizeChart.id,
142	      name: best.sizeChart.name,
143	      category: best.sizeChart.category,
144	      type: best.sizeChart.type,
145	      data: parsedData,
146	      assignmentType: best.assignmentType,
147	    };
148	
149	    return corsJson(response);
150	  } catch {
151	    return corsJson(
152	      { error: "Unable to load size chart. Please try again." },
153	      { status: 500 },
154	    );
155	  }
156	};
